function revisionGuideFor(slug: string): RevisionGuide {
  return revisionGuides[slug] || { terms: [], rules: [], method: [], pitfalls: [] };
}

const pendingSubjects = [
  "بقية وحدات كل مادة",
  "التدقيق النهائي مقابل الطبعة المدرسية",
];

function saveAttempt(slug: string, tier: Tier, score: number, total: number) {
  try {
    const key = "yemen-study-grade12-learning-attempts";
    const existing = JSON.parse(localStorage.getItem(key) || "[]");
    const rows = Array.isArray(existing) ? existing.slice(-49) : [];
    rows.push({ subject: slug, tier, score, total, date: new Date().toISOString() });
    localStorage.setItem(key, JSON.stringify(rows));
  } catch {
    // Scoring works even when local browser storage is disabled.
  }
}

export default function Grade12LearningHubPage() {
  const [searchParams, setSearchParams] = useSearchParams();
  const requestedSlug = searchParams.get("subject") || "physics";
  const current = modules.find((module) => module.slug === requestedSlug) || modules[0];
  const [tier, setTier] = useState<Tier>("good");
  const [answers, setAnswers] = useState<Record<string, number>>({});
  const [revealed, setRevealed] = useState<string[]>([]);
  const [submitted, setSubmitted] = useState(false);
  const [moduleTrackFilter, setModuleTrackFilter] = useState("الكل");
  const [moduleQuery, setModuleQuery] = useState("");
  
  const questions = useMemo(() => current.questions[tier], [current, tier]);
  const answered = questions.filter((question) => answers[question.id] !== undefined).length;
  const score = questions.filter((question) => answers[question.id] === question.answer).length;

  const chooseModule = (slug: string) => {
    setSearchParams({ subject: slug });
    setTier("good");
    setAnswers({});
    setRevealed([]);
    setSubmitted(false);
  };
  const chooseTier = (next: Tier) => {
    setTier(next);
    setAnswers({});
    setRevealed([]);
    setSubmitted(false);
  };
  const resetQuiz = () => {
    setAnswers({});
    setRevealed([]);
    setSubmitted(false);
  };
  const checkOne = (id: string) => setRevealed((old) => old.includes(id) ? old : [...old, id]);
  const submitQuiz = () => {
    if (submitted || answered !== questions.length) return;
    saveAttempt(current.slug, tier, score, questions.length);
    setSubmitted(true);
  };
  const printDocument = (kind: "summary" | "exam") => {
    document.body.dataset.g12LearningPrint = kind;
    const clean = () => {
      delete document.body.dataset.g12LearningPrint;
      window.removeEventListener("afterprint", clean);
    };
    window.addEventListener("afterprint", clean);
    window.print();
    // Some mobile browsers do not dispatch afterprint. The dataset only affects print media.
  };

  const lessonCards = modules.map((module) => ({ slug: module.slug, name: module.name, track: module.track, detail: module.coverage + " · " + module.title, status: "متاح", href: "/grade-12-learning?subject=" + module.slug }));
  const visibleLessonCards = lessonCards.filter((card) =>
    (moduleTrackFilter === "الكل" || card.track === moduleTrackFilter) &&
    (moduleQuery.trim() === "" || (card.name + " " + card.detail).toLocaleLowerCase("ar").includes(moduleQuery.trim().toLocaleLowerCase("ar")))
  );

  return <main className="container page g12-learning-page">
    <div className="breadcrumbs"><Link to="/">الرئيسية</Link><span>›</span><Link to="/grade/grade-12">الصف الثالث الثانوي</Link><span>›</span><b>المنهج العدني 2026 · الشرح والملخصات والاختبارات</b></div>
    <header className="g12-learning-header">
      <div><span className="eyebrow">منهج عدن · الصف الثالث الثانوي 2026</span><h1>مركز شرح ومراجعة مواد الصف الثالث الثانوي.</h1><p>محاور أكاديمية داخل الموقع تشمل الشرح والأمثلة المحلولة ومذكرات المراجعة المفصلة القابلة للحفظ PDF، مع اختبارات منفصلة حسب مستوى الصعوبة.</p></div>
      <div className="g12-learning-header-meta"><BookOpen size={20}/><span>{modules.length} محوراً · الشرح والاختبارات داخل الموقع</span></div>
    </header>

    <section className="g12-learning-notice"><ShieldCheck size={18}/><p>وحدات الفيزياء الست في هذا القسم مرتبة وفق ملخص الأستاذ محمد عبده الدوكري المرفق (144 صفحة، الصفحات 1–143 للمحتوى الدراسي). عناوين الوحدات ومصطلحاتها وقوانينها محفوظة، أما الشروح والأمثلة والأسئلة فمصاغة بصورة تعليمية مستقلة ولا تنقل صفحات الملزمة حرفياً. بقية المواد تعتمد على فهارس المقررات المتاحة.</p></section>

    <div className="g12-learning-layout">
      <aside className="g12-learning-nav">
        <h2>مواد الصف الثالث الثانوي · منهج عدن</h2>
        <input className="g12-learning-search" type="search" value={moduleQuery} onChange={(event) => setModuleQuery(event.target.value)} placeholder="ابحث عن مادة أو وحدة..." aria-label="ابحث عن مادة أو وحدة"/>
        <div className="g12-learning-track-filters" aria-label="تصفية حسب المسار">
          {["الكل", "القسم العلمي", "القسم الأدبي", "المواد المشتركة"].map((track) => <button key={track} type="button" onClick={() => setModuleTrackFilter(track)} className={moduleTrackFilter === track ? "active" : ""}>{track}</button>)}
        </div>
        <p className="g12-learning-nav-count">عرض {visibleLessonCards.length} من {lessonCards.length} محوراً</p>
        {visibleLessonCards.map((card) => <Link key={card.slug} to={card.href} className={card.slug === current.slug ? "g12-learning-nav-card active" : "g12-learning-nav-card"} onClick={(event) => { if (modules.some((module) => module.slug === card.slug)) { event.preventDefault(); chooseModule(card.slug); } }}>
          <span className="g12-learning-nav-icon">{card.name.includes("الكيمياء") ? <FlaskConical size={18}/> : card.name.includes("الرياضيات") ? <Calculator size={18}/> : <BookOpen size={18}/>}</span>
          <span><b>{card.name}</b><small>{card.detail}</small></span>
          <span className="g12-learning-nav-status">{card.status}</span>
        </Link>)}
        {visibleLessonCards.length === 0 && <p className="g12-learning-empty">لا توجد نتائج مطابقة. جرّب كلمة بحث أخرى.</p>}
        <div className="g12-learning-pending"><b>الوحدات المتبقية قيد المراجعة النهائية</b><p>تظهر هنا المحاور المنشورة في المواد العلمية والأدبية والمشتركة. يُستكمل التدقيق النهائي مع النسخة المدرسية المطبوعة، كما تضاف تفاصيل النصوص الأدبية دون إعادة نشر نصوص محمية.</p><div>{pendingSubjects.map((subject) => <span key={subject}>{subject}</span>)}</div></div>
      </aside>

      <div className="g12-learning-main">
        <section className="g12-learning-panel">
          <div className="g12-learning-course-head">
            <div><span className="eyebrow">منهج عدن 2026 · {current.track} · {current.coverage}</span><h2>{current.name}: {current.title}</h2><p>{current.introduction}</p></div>
            <span className="g12-learning-badge">شرح وملخص واختبار</span>
          </div>
          <div className="g12-learning-outcomes"><b>أهداف التعلم</b><ul>{current.outcomes.map((item) => <li key={item}>{item}</li>)}</ul></div>
          <div className="g12-learning-section-list">
            {current.sections.map((section) => <article key={section.title} className="g12-learning-section">
              <h3>{section.title}</h3><p>{section.body}</p>
              {section.formula && <div className="g12-learning-formula" dir="ltr">{section.formula}</div>}
              {section.bullets && <ul>{section.bullets.map((bullet) => <li key={bullet}>{bullet}</li>)}</ul>}
            </article>)}
          </div>
          <div className="g12-learning-example">
            <span>تطبيق محلول</span><h3>{current.example.title}</h3><p>{current.example.prompt}</p>
            <ol>{current.example.steps.map((step) => <li key={step}>{step}</li>)}</ol>
            <b>{current.example.result}</b>
          </div>
          <div className="g12-learning-summary">
            <div className="g12-learning-summary-head"><div><span className="eyebrow">ورقة المراجعة · ملخص تفصيلي</span><h3>مذكرة مراجعة الدرس</h3><p>تعريفات أساسية، قواعد وقوانين، خطوات حل، وتنبيهات على الأخطاء الشائعة.</p></div><button className="btn btn-outline g12-no-print" type="button" onClick={() => printDocument("summary")}><Download size={16}/> حفظ الملخص PDF</button></div>
            <div className="g12-revision-grid">
              <section><h4>المصطلحات والتعريفات</h4><ul>{revisionGuideFor(current.slug).terms.map((item) => <li key={item}>{item}</li>)}</ul></section>
              <section><h4>القواعد والعلاقات المهمة</h4><ul>{revisionGuideFor(current.slug).rules.map((item) => <li key={item}>{item}</li>)}</ul></section>
              <section><h4>خطوات التعامل مع الأسئلة</h4><ol>{revisionGuideFor(current.slug).method.map((item) => <li key={item}>{item}</li>)}</ol></section>
              <section><h4>أخطاء شائعة يجب تجنبها</h4><ul>{revisionGuideFor(current.slug).pitfalls.map((item) => <li key={item}>{item}</li>)}</ul></section>
            </div>
            <div className="g12-learning-summary-quick"><h4>خلاصة سريعة للحفظ</h4><ol>{current.summary.map((item) => <li key={item}>{item}</li>)}</ol></div>
          </div>
          <footer className="g12-learning-source"><ShieldCheck size={17}/><div><b>مراجع الوحدة والشرح</b>{current.sourceNote && <small>{current.sourceNote}</small>}<a href={current.curriculumSource.url} target="_blank" rel="noreferrer">{current.curriculumSource.title}</a><a href={current.source.url} target="_blank" rel="noreferrer">{current.source.title}</a><small>فهرس الكتاب يُستخدم لمطابقة ترتيب الموضوعات. الشرح والأمثلة والأسئلة صيغت من جديد، والمرجع العلمي للتحقق من المفاهيم.</small></div></footer>
        </section>

        <section className="g12-learning-panel g12-learning-quiz">
          <div className="g12-learning-panel-title"><span><FileText size={20}/></span><div><h2>اختبر فهمك</h2><p>ثلاث درجات من الصعوبة، مع التصحيح وتفسير الإجابات.</p></div></div>
          <div className="g12-learning-tier-switch">
            {(["good", "hard", "hardest"] as Tier[]).map((value) => <button key={value} type="button" onClick={() => chooseTier(value)} className={tier === value ? "active" : ""}><b>{tierDetails[value].label}</b><small>{tierDetails[value].subtitle}</small></button>)}
          </div>
          <div className="g12-learning-quiz-meta"><span><FileText size={14}/>{questions.length} أسئلة</span><span><Clock3 size={14}/>{tierDetails[tier].minutes} دقيقة</span><span>الدرجة {questions.length}</span></div>
          <div className="g12-learning-questions">
            {questions.map((question, index) => <article key={question.id} className="g12-learning-question">
              <div className="g12-learning-question-num">السؤال {index + 1}</div>
              <h3>{question.prompt}</h3>
              <div className="g12-learning-options">{question.options.map((option, optionIndex) => {
                const selected = answers[question.id] === optionIndex;
                const reveal = revealed.includes(question.id) || submitted;
                const right = question.answer === optionIndex;
                return <button key={optionIndex} type="button" disabled={submitted || revealed.includes(question.id)} onClick={() => setAnswers((old) => ({ ...old, [question.id]: optionIndex }))} className={reveal && right ? "correct" : reveal && selected && !right ? "wrong" : selected ? "selected" : ""}><i>{["أ", "ب", "ج", "د"][optionIndex]}</i><span>{option}</span></button>;
              })}</div>
              {revealed.includes(question.id) || submitted ? <div className="g12-learning-explanation"><b>{answers[question.id] === question.answer ? "إجابة صحيحة" : "الإجابة الصحيحة موضحة أدناه"}</b><p>{question.explanation}</p></div> : <button type="button" className="g12-learning-check" disabled={answers[question.id] === undefined} onClick={() => checkOne(question.id)}>تحقق من الإجابة</button>}
            </article>)}
          </div>
          <div className="g12-learning-quiz-footer g12-no-print"><span>أجبت عن {answered} من {questions.length}</span><div><button type="button" className="btn btn-outline" onClick={resetQuiz}><RotateCcw size={15}/> إعادة</button><button type="button" className="btn btn-outline" onClick={() => printDocument("exam")}><Download size={15}/> ورقة اختبار PDF</button><button type="button" className="btn btn-primary" disabled={submitted || answered !== questions.length} onClick={submitQuiz}>تصحيح الاختبار <CheckCircle2 size={15}/></button></div></div>
          {submitted && <div className="g12-learning-result"><Trophy size={24}/><div><b>نتيجتك {score} من {questions.length}</b><span>{Math.round(score / questions.length * 100)}% — راجع التفسيرات قبل الانتقال للمستوى التالي.</span></div></div>}
        </section>
      </div>
    </div>

    <section className="g12-learning-print-summary">
      <header><b>Yemen Study</b><span>منهج عدن 2026 · الصف الثالث الثانوي · {current.name}</span><h1>{current.title}</h1><p>{current.coverage} · مذكرة مراجعة تفصيلية</p></header>
      <h2>أهداف التعلم</h2><ul>{current.outcomes.map((item) => <li key={item}>{item}</li>)}</ul>
      {current.sections.map((section) => <section key={section.title}><h3>{section.title}</h3><p>{section.body}</p>{section.formula && <p dir="ltr">{section.formula}</p>}{section.bullets && <ul>{section.bullets.map((bullet) => <li key={bullet}>{bullet}</li>)}</ul>}</section>)}
      <section><h2>مثال محلول</h2><h3>{current.example.title}</h3><p>{current.example.prompt}</p><ol>{current.example.steps.map((step) => <li key={step}>{step}</li>)}</ol><b>{current.example.result}</b></section>
      <section className="g12-print-revision"><h2>مذكرة مراجعة مركزة</h2>
        <h3>المصطلحات والتعريفات</h3><ul>{revisionGuideFor(current.slug).terms.map((item) => <li key={item}>{item}</li>)}</ul>
        <h3>القواعد والعلاقات المهمة</h3><ul>{revisionGuideFor(current.slug).rules.map((item) => <li key={item}>{item}</li>)}</ul>
        <h3>خطوات التعامل مع الأسئلة</h3><ol>{revisionGuideFor(current.slug).method.map((item) => <li key={item}>{item}</li>)}</ol>
        <h3>أخطاء شائعة</h3><ul>{revisionGuideFor(current.slug).pitfalls.map((item) => <li key={item}>{item}</li>)}</ul>
      </section>
      <section><h2>خلاصة للحفظ</h2><ol>{current.summary.map((item) => <li key={item}>{item}</li>)}</ol></section>
      <footer>فهرس الموضوع: {current.curriculumSource.title}. مرجع التحقق العلمي: {current.source.title}. مذكرة أصلية للمراجعة وليست نشرة رسمية صادرة عن الوزارة.</footer>
    </section>

    <section className="g12-learning-print-exam">
      <header><b>Yemen Study</b><span>الصف الثالث الثانوي · {current.name}</span><h1>اختبار: {current.title}</h1><p>المستوى: {tierDetails[tier].label} · الزمن المقترح: {tierDetails[tier].minutes} دقيقة</p></header>
      <div className="g12-learning-print-student"><span>اسم الطالب: ........................................</span><span>التاريخ: .... / .... / ........</span></div>
      {questions.map((question, index) => <article key={question.id}><b>{index + 1}. {question.prompt}</b><ol type="A">{question.options.map((option) => <li key={option}>{option}</li>)}</ol></article>)}
      <footer>اختبار تدريبي أصلي داخل Yemen Study، وليس امتحاناً وزارياً رسمياً.</footer>
    </section>

    <p className="g12-learning-final-note"><ShieldCheck size={15}/> يضم المركز حالياً {modules.length} محوراً تعليمياً في مواد العلمي والأدبي والمشتركة، تغطي وحدات من الكتب في الفيزياء والكيمياء والأحياء والرياضيات والجغرافيا والتاريخ واللغة العربية والإنجليزية والقرآن والإيمان والحديث والفقه والسيرة والفلسفة والمنطق وعلم النفس والخرائط. هذه تغطية واسعة للوحدات وليست ادعاءً بأن كل درس في كل كتاب قد اكتمل؛ راجع فهرس الكتاب المدرسي للموضوعات المتبقية.</p>
  </main>;
}
